<script lang="ts">
import SvgIcon from "$lib/components/ui/Icon.svelte";
import Card from "$lib/components/ui/Card.svelte";
import CardHeader from "$lib/components/ui/CardHeader.svelte";
import CardTitle from "$lib/components/ui/CardTitle.svelte";
import CardContent from "$lib/components/ui/CardContent.svelte";
import Input from "$lib/components/ui/Input.svelte";
import Button from "$lib/components/ui/Button.svelte";
import BarList from "$lib/components/reports/BarList.svelte";
import Badge from "$lib/components/ui/Badge.svelte";


type Dashboard = { available: Record<string, boolean>; workforce?: { metrics: Record<string, number>; breakdown: Array<{ label: string; value: number }> }; attendance?: { total: number; breakdown: Array<{ status: string; value: number }> }; leave?: { total: number; breakdown: Array<{ status: string; value: number }> }; expenses?: { total: number; amount: number; breakdown: Array<{ status: string; value: number }> }; recruitment?: Record<string, number>; projectsTasks?: Record<string, number | null>; payroll?: { runs: Array<{ status: string; value: number }>; totals: Record<string, number> } };
function title(value: string) { return value.replaceAll("_", " ").replace(/\b\w/g, (character) => character.toUpperCase()); }

import {untrack} from 'svelte';import {api} from '$lib/client/api';
let data=$state<Dashboard|null>(null),from=$state(''),to=$state(''),loading=$state(true),error=$state('');
async function load(){loading=true;error='';const params=new URLSearchParams({kind:'dashboard'});if(from)params.set('from',from);if(to)params.set('to',to);
try{data=(await api<{data:Dashboard}>('/api/app/reports?'+params)).data;}catch(e){error=(e as Error).message;}finally{loading=false;}}
const setFrom=(value:string)=>from=value;const setTo=(value:string)=>to=value;
$effect(()=>{from;to;untrack(()=>void load());});

</script>
{#if loading}<Card><CardContent class="p-6 text-sm text-muted">Loading organization reports…</CardContent></Card>{:else if error}<Card><CardContent class="space-y-3 p-6"><p role="alert" class="text-sm text-danger">{error}</p><Button onclick={()=>void load()}>Try again</Button></CardContent></Card>{:else if data}
<div class="space-y-5"><Card><CardHeader><CardTitle>Report filters</CardTitle></CardHeader><CardContent class="flex flex-wrap items-end gap-3"><div><label class="text-sm font-medium" for="report-from">From</label><Input id="report-from" type="date" value={from} onchange={(event) => setFrom(event.currentTarget.value)} /></div><div><label class="text-sm font-medium" for="report-to">To</label><Input id="report-to" type="date" value={to} onchange={(event) => setTo(event.currentTarget.value)} /></div><Button onclick={() => void load()}>Apply filters</Button></CardContent></Card><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{#if data.workforce}{#each Object.entries(data.workforce.metrics) as [key, value]}<Card><CardContent class="p-5"><p class="text-sm text-muted">{title(key)}</p><p class="mt-2 text-3xl font-bold">{value}</p></CardContent></Card>{/each}{/if}{#if data.attendance}<Card><CardContent class="p-5"><p class="text-sm text-muted">Attendance records</p><p class="mt-2 text-3xl font-bold">{data.attendance.total}</p></CardContent></Card>{/if}{#if data.leave}<Card><CardContent class="p-5"><p class="text-sm text-muted">Leave requests</p><p class="mt-2 text-3xl font-bold">{data.leave.total}</p></CardContent></Card>{/if}{#if data.expenses}<Card><CardContent class="p-5"><p class="text-sm text-muted">Expense amount</p><p class="mt-2 text-3xl font-bold">₹{data.expenses.amount.toLocaleString("en-IN")}</p></CardContent></Card>{/if}</div><div class="grid gap-5 lg:grid-cols-2">{#if data.workforce}<Card><CardHeader><CardTitle>Department distribution</CardTitle></CardHeader><CardContent><BarList rows={data.workforce.breakdown} /></CardContent></Card>{/if}{#if data.attendance}<Card><CardHeader><CardTitle>Attendance status</CardTitle></CardHeader><CardContent><BarList rows={data.attendance.breakdown.map((row) => ({ label: row.status, value: row.value }))} /></CardContent></Card>{/if}{#if data.leave}<Card><CardHeader><CardTitle>Leave status</CardTitle></CardHeader><CardContent><BarList rows={data.leave.breakdown.map((row) => ({ label: row.status, value: row.value }))} /></CardContent></Card>{/if}{#if data.expenses}<Card><CardHeader><CardTitle>Expense status</CardTitle></CardHeader><CardContent><BarList rows={data.expenses.breakdown.map((row) => ({ label: row.status, value: row.value }))} /></CardContent></Card>{/if}{#if data.recruitment}<Card><CardHeader><CardTitle>Recruitment pipeline</CardTitle></CardHeader><CardContent class="grid grid-cols-2 gap-3">{#each Object.entries(data.recruitment) as [key, value]}<div class="rounded-lg border p-3"><p class="text-xs text-muted">{title(key)}</p><p class="mt-1 text-xl font-bold">{value}</p></div>{/each}</CardContent></Card>{/if}{#if data.projectsTasks}<Card><CardHeader><CardTitle>Projects & tasks</CardTitle></CardHeader><CardContent class="grid grid-cols-2 gap-3">{#each Object.entries(data.projectsTasks).filter(([, value]) => value !== null) as [key, value]}<div class="rounded-lg border p-3"><p class="text-xs text-muted">{title(key)}</p><p class="mt-1 text-xl font-bold">{value}</p></div>{/each}</CardContent></Card>{/if}{#if data.payroll}<Card><CardHeader><CardTitle>Payroll summary</CardTitle><Badge>Permission controlled</Badge></CardHeader><CardContent class="grid grid-cols-2 gap-3">{#each Object.entries(data.payroll.totals) as [key, value]}<div class="rounded-lg border p-3"><p class="text-xs text-muted">{title(key)}</p><p class="mt-1 text-xl font-bold">₹{value.toLocaleString("en-IN")}</p></div>{/each}</CardContent></Card>{/if}</div>{#if !Object.values(data.available).some(Boolean)}<Card><CardContent class="p-6 text-sm text-muted">No reports are available for your role.</CardContent></Card>{/if}</div>
{/if}